import {journeyStages,robotModules,robotRoot,workshopJourney,mechanismJourney,architectureJourney,weekJourney,stageForLesson} from './data/journey.js';
import {journeyStatus,nextJourneyStage} from './journey-state.js';
import {lessons} from './data/curriculum.js';
import {architectures,architectureGroups} from './data/architectures.js';
import {concepts} from './data/concepts.js';
import {workshops} from './data/workshops.js';
import {escapeHTML as e} from './state.js';

const stage=id=>journeyStages.find(s=>s.id===id);
const moduleFor=id=>robotModules.find(m=>m.id===id);
const url=id=>`#/journey/${id}`;
const sourceURL=path=>`https://github.com/TatenLee/model-craft/blob/main/${robotRoot}${path}`;
const stageLink=id=>{const s=stage(id);return `<a href="${url(id)}">${s.number} · ${e(s.title)} →</a>`;};
const fullPath=path=>robotRoot+path;
const heading=(title,body)=>`<div class="page-heading"><div><span class="eyebrow">BUILD ONE ROBOT · FOLLOW THE REASON</span><h1>${e(title)}</h1><p>${e(body)}</p></div></div>`;
const links=refs=>refs.map(r=>`<a class="btn btn-small" href="${e(r.href)}" ${r.href.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${e(r.label)} ↗</a>`).join('');

export function journeyPage(id,state,exercises,editor){
 if(!id)return home(state,exercises);
 const s=stage(id);if(!s)return heading('没有找到这一站','从机器人主线重新选择阶段。')+'<a href="#/journey">返回主线</a>';
 const ex=exercises.find(x=>x.id===s.exerciseId),record=state.journey?.[s.id]||{},status=journeyStatus(s,state,ex);
 return `<div class="robot-journey">${heading(`${s.number} · ${s.title}`,'先知道现在缺什么，再改一个模块，最后用证据交接给下一站。')}<div class="journey-stage-nav"><a href="#/journey">← 整条主线</a><a href="#/blueprint/${s.module}">查看本次模块在工程里的位置 →</a></div><div class="journey-layout"><article class="journey-main"><section class="panel panel-pad"><div class="row wrap"><span class="badge">${e(moduleFor(s.module).name)}</span><span class="badge badge-gray">本阶段约 ${s.hours} 小时 · 分多次完成</span><span class="badge">${status.mode==='reuse'?'复用积木路线':'亲手构造路线'}</span></div><div class="journey-cause"><div><span>已经拥有</span><p>${e(s.before)}</p></div><div><span>新任务暴露的问题</span><p>${e(s.problem)}</p></div><div><span>先诊断原因</span><p>${e(s.diagnosis)}</p></div><div><span>这一次只改什么</span><p>${e(s.upgrade)}</p></div></div>${s.previous?`<p class="small muted">这一步承接 ${stageLink(s.previous)}。已有相应能力可以直接进入，不锁定阅读顺序。</p>`:'<p>起点只需要会读变量、循环和函数。所需数学在计算发生的位置解释。</p>'}</section><section class="panel panel-pad"><h2>今天停在哪里？</h2>${sessionChooser(state)}<div id="journey-session-plan">${sessionPlan(state.journeyMinutes||60)}</div><nav class="journey-anchors" aria-label="本阶段操作顺序"><button class="btn btn-small" data-journey-scroll="journey-explain">① 理解问题</button><button class="btn btn-small" data-journey-scroll="journey-build">② 改一个模块</button><button class="btn btn-small" data-journey-scroll="journey-code">③ 运行与检查</button><button class="btn btn-small" data-journey-scroll="journey-review">④ 写交接记录</button></nav></section><section class="panel panel-pad journey-reading" id="journey-explain" tabindex="-1"><h2>① 为什么现在需要它？</h2>${s.teaching.map(t=>`<section><h3>${e(t.title)}</h3>${t.body.map(p=>`<p>${e(p)}</p>`).join('')}</section>`).join('')}<div class="journey-worked"><h3>和我一起推演</h3><ol>${s.worked.map(t=>`<li>${e(t)}</li>`).join('')}</ol></div>${miniLab(s.id)}${deepReading(s)}</section><section class="panel panel-pad" id="journey-build" tabindex="-1"><h2>② 在同一副骨架上改造</h2><div class="journey-mode" role="group" aria-label="选择本阶段建造方式"><label><input type="radio" name="journey-mode" value="build" ${status.mode==='build'?'checked':''}> 亲手构造，理解内部计算</label><label><input type="radio" name="journey-mode" value="reuse" ${status.mode==='reuse'?'checked':''}> 使用已有积木，重点验收接口</label></div><p class="callout" id="journey-reuse-note">${e(status.mode==='reuse'?s.reuse:'按下面步骤实现关键接口。完整参考工程可直接下载；你修改自己的练习区并记录版本，不需要凭空搭建每个文件。')}</p><div class="journey-interface"><span>这个模块的稳定契约</span><code>${e(moduleFor(s.module).contract)}</code><p>${e(moduleFor(s.module).role)}</p></div><h3>本次关注的真实文件</h3><ul class="journey-files">${s.files.map((path,i)=>`<li><b>${i===0?'主要改动 / 阅读':'联动检查'}</b><a href="${sourceURL(path)}" target="_blank" rel="noopener noreferrer"><code>${e(fullPath(path))}</code> ↗</a></li>`).join('')}</ul><p class="small muted">下载包包含完整参考实现；这是最终目录蓝图。主线每一站只展开涉及的模块，已有调用者和评测尽量保持不变。权重不保证跨结构兼容。</p><ol class="journey-tasks">${s.tasks.map((t,i)=>`<li><h3>${e(t.action)}</h3><p><b>应该看到：</b>${e(t.expected)}</p><details><summary>卡住时先查哪里</summary><p>${e(t.trouble)}</p></details><label><input class="journey-task" type="checkbox" value="${i}" ${record.tasks?.includes(i)?'checked':''}> 我已操作并核对这一项</label></li>`).join('')}</ol>${s.command?`<h3>在本地继续同一个工程</h3><p>下载工程后，在 <code>projects/robot-workbench</code> 目录运行。${/robot\.cli (scalar|plan|observe)( |$)/.test(s.command)?'这个命令只需要 Python 标准库，无需安装 PyTorch；也可以先完成下方网页练习。':'神经网络实验需按工程说明安装一次 PyTorch。'}</p><pre><code>${e(s.command)}</code></pre><p class="small muted">${s.command.includes('robot.cli agent')?'执行前需已有 full MLP checkpoint：先运行 <code>python -m robot.cli train --arch mlp --steps 400</code>。':''}默认运行产物写入本地忽略目录。</p>`:'<p>本阶段先完成机制与接口验收，实际训练命令在下方关联工作坊中；主线明确区分已实现基线与进阶迁移。</p>'}<div class="row wrap"><a class="btn" href="./downloads/model-craft-projects.zip" download>下载同一套工程</a><a class="btn" href="https://github.com/TatenLee/model-craft/blob/main/projects/robot-workbench/README.md" target="_blank" rel="noopener noreferrer">安装、命令与模块范围</a></div></section><section class="panel panel-pad" id="journey-code" tabindex="-1"><h2>③ 实现一个接口，当场验证</h2><p>本阶段要验证：${e(ex.goal||ex.summary)}。旧练习已通过且代码未改变时会复用成绩，不要求重复提交。</p>${editor(ex)}</section><section class="panel panel-pad"><h2>把原因讲清楚，再继续</h2>${s.checks.map((q,i)=>`<fieldset class="journey-question" data-index="${i}"><legend>${e(q.prompt)}</legend>${q.options.map((o,j)=>`<label><input type="radio" name="journey-check-${i}" value="${j}" ${record.answers?.[i]===j?'checked':''}> ${e(o)}</label>`).join('')}<div class="journey-answer" role="status">${Number.isInteger(record.answers?.[i])?answer(q,record.answers[i]):'先作答，再查看解析。'}</div></fieldset>`).join('')}</section><section class="panel panel-pad" id="journey-review" tabindex="-1"><h2>④ 给下一站留一份交接</h2><p>写下本次症状、改动文件/配置、实际结果和仍未解决的问题。至少 20 字；真实实验由你自查，系统不把勾选当成效果认证。</p><label for="journey-note">我的实际观察</label><textarea id="journey-note" class="field" rows="6" placeholder="原来……；本次只改……；运行后看到……；还不能……">${e(record.note||'')}</textarea><p id="journey-note-status" class="small muted" role="status">记录保存在本机，可随学习备份导出。</p><div id="journey-completion">${journeyCompletion(s,state,ex)}</div></section><section class="panel panel-pad journey-handoff"><span class="eyebrow">故事继续 · 下一次需求为什么出现</span><h2>${s.nextId?e(stage(s.nextId).title):'回到问题，而不是重新背目录'}</h2><p>${e(s.next)}</p><div class="row wrap">${s.nextId?`<a class="btn btn-primary" href="${url(s.nextId)}">进入 ${stage(s.nextId).number} →</a>`:'<a class="btn btn-primary" href="#/blueprint">带着失败回到对应模块 →</a>'}<a class="btn" href="#/journey">回到整条路线</a></div></section>${s.refs.length?`<section class="panel panel-pad"><h2>到这里才需要展开的材料</h2><p>这些资料服务于当前问题。完成阅读或练习后，回到本页记录结果，无需再按另一套顺序重学。</p><div class="row wrap">${links(s.refs)}</div></section>`:''}</article><aside class="journey-aside"><section class="panel panel-pad"><h3>机器人当前装到哪了？</h3>${assembly(s)}<a class="text-link" href="#/blueprint/${s.module}">查看完整目录与接头 →</a></section><section class="panel panel-pad"><h3>这一段的来龙去脉</h3><div class="journey-neighbors">${[s.previous,s.id,s.nextId].filter(Boolean).map(id=>`<div class="${id===s.id?'current':''}">${stageLink(id)}</div>`).join('')}</div></section></aside></div></div>`;
}
const answer=(q,selected)=>`<b>${selected===q.answer?'✓ 原因理解正确':'再检查这个因果关系'}</b><p>${e(q.explanation)}</p>`;
function sessionChooser(state){return `<div class="journey-time" role="group" aria-label="今天可用学习时间">${[30,60,120].map(n=>`<button class="btn btn-small ${(state.journeyMinutes||60)===n?'btn-primary':''}" data-journey-minutes="${n}" aria-pressed="${(state.journeyMinutes||60)===n}">${n} 分钟</button>`).join('')}</div>`;}
const sessionPlan=n=>`<p>${n===30?'今天只完成一个小闭环：读“新问题”与一段解释 → 手算一个例子 → 写下你现在能解释的变化。下次从同页继续。':n===60?'今天先读问题与推演，再实现本页接口并运行样例；留下失败与疑问。完整本地实验可以下一次继续。':'今天完成讲解、代码检查和一次本地对照，把结果写进交接单；遇到失败先定位，不靠阅读更多缩写跳过。'}</p><p class="small muted">时间是建议，不设倒计时门槛；一个阶段可跨多天。完成取决于当前代码和观察证据。</p>`;

function home(state,exercises){
 const next=nextJourneyStage(state,exercises),complete=journeyStages.filter(s=>journeyStatus(s,state,exercises.find(x=>x.id===s.exerciseId)).complete).length;
 return `<div class="robot-journey">${heading('从 wx+b 出发，一步步造出机器人。','同一个任务、同一副工程骨架。先遇到问题，再增加能力；每个概念都有它出现的理由。')}<section class="panel panel-pad journey-hero"><div><span class="eyebrow">我们的任务</span><h2>“先去红色目标，再去蓝色目标；没到就别说完成。”</h2><p>从模拟桌面滑台开始，逐步接入感知、世界模型、任务大脑、规划和 Agent 工具循环，再把接口映射到 OmniFM。先做可检查的小系统，进阶模型通过同一模块位置学习与迁移。</p><div class="row wrap"><a class="btn btn-primary" href="${url(next.id)}">${complete?'继续':'开始'} ${next.number} · ${e(next.title)} →</a><a class="btn" href="#/blueprint">先看机器人最终骨架</a></div></div><div class="journey-robot-scene" aria-label="任务示意：机器人先到红色，再到蓝色"><div class="journey-scene-track"><span>●<small>红色目标</small></span><span class="journey-car">▣<small>模拟机器人</small></span><span>●<small>蓝色目标</small></span></div><p>指令 → 感知 → 预测 → 选择动作<br>↶ 观察真实结果，检查是否完成</p></div></section><div class="journey-summary"><span><b>${complete}/${journeyStages.length}</b> 阶段交接已完成</span><span><b>${journeyStages.reduce((n,s)=>n+s.hours,0)} 小时</b> 主线规划预算</span><span><b>两种建造方式</b> 亲手实现 / 复用积木</span></div><section class="panel panel-pad"><h2>这次怎样学，才不会突然从 A 跳到 B？</h2><ol class="journey-rules"><li><b>先看当前失败。</b> 如果直线已经够用，就保留它；升级来自新增任务或证据。</li><li><b>找到工程里的位置。</b> 输入、输出、状态和调用者固定下来，再选内部算法。</li><li><b>一次改一个关键变量。</b> 先解释预期，再做代码与实验，记录没解决的部分。</li><li><b>已有好积木就复用。</b> 可跳过内部重造，但仍验收接口、数据分布与效果。</li></ol><p>每个阶段分“理解问题 → 改造模块 → 运行检查 → 交接下一站”。原来的周课、结构图与 P/M 项目已归入参考库，会在需要时展开；旧记录保留，不再要求走多套学习顺序。</p>${sessionChooser(state)}<div id="journey-session-plan">${sessionPlan(state.journeyMinutes||60)}</div></section><h2>一条有因果的建造路线</h2><ol class="journey-road">${journeyStages.map((s,i)=>{const status=journeyStatus(s,state,exercises.find(x=>x.id===s.exerciseId));return `<li><a class="panel journey-road-card ${s.id===next.id?'next':''}" href="${url(s.id)}"><div class="journey-road-number">${status.complete?'✓':s.number}</div><div><div class="between wrap"><span class="eyebrow">${e(moduleFor(s.module).name)} · 约 ${s.hours} 小时</span><span class="small muted">${status.complete?'已有交接记录':s.id===next.id?'建议从这里继续':'可直接查阅'}</span></div><h3>${e(s.title)}</h3><p><b>为什么到这一步：</b>${e(s.problem)}</p><p class="journey-road-change"><b>装上什么：</b>${e(s.upgrade)}</p></div></a>${i<journeyStages.length-1?`<div class="journey-road-bridge"><span aria-hidden="true">↓</span> ${e(s.next)}</div>`:''}</li>`;}).join('')}</ol><section class="panel panel-pad"><h2>主线、扩展和实际工程的边界</h2><p>预算包含思考、实现和实验，约每周 10 小时可安排为 12 周。各阶段的 P 项目作为同一任务的展开材料，不重复叠加全部工时。浏览器检查是机制级；本地工程提供可运行的小型世界模型和任务闭环。DINO、语言基座、完整 KDA、生成策略与多卡方案按模块接入，需要各自训练或实测。</p><div class="row wrap"><a class="btn" href="#/library">按需查阅原课程与所有结构</a><a class="btn" href="./downloads/model-craft-projects.zip" download>下载机器人参考工程</a></div></section></div>`;
}
function assembly(current){const order=journeyStages.indexOf(current);return `<ul class="journey-assembly">${robotModules.map(m=>{const installed=journeyStages.findIndex(s=>s.id===m.stage)<=order;return `<li class="${m.id===current.module?'current':installed?'installed':'future'}"><a href="#/blueprint/${m.id}"><b>${e(m.name)}</b><small>${m.id===current.module?'本次改动':installed?'已有接口 / 继续复用':'后续需求再展开'}</small></a></li>`;}).join('')}</ul>`;}
function deepReading(s){return s.lessons.length?`<div class="journey-deep"><h3>需要更细的解释？在这里继续展开</h3><p>这些原有课文已放到当前问题下面；先看上面的因果，再按需要展开，不必跳到另一条课程路线。</p>${s.lessons.map(id=>{const l=lessons.find(x=>x.id===id);return `<details class="journey-reference"><summary>${e(l.title)}</summary><dl>${l.terms.map(t=>`<dt>${e(t.name)}</dt><dd>${e(t.meaning)}</dd>`).join('')}</dl>${l.sections.map(section=>`<h4>${e(section.title)}</h4>${section.body.map(p=>`<p>${e(p)}</p>`).join('')}`).join('')}<h4>${e(l.worked.title)}</h4><ol>${l.worked.steps.map(p=>`<li>${e(p)}</li>`).join('')}</ol><a href="#/lesson/${id}">完整例子、更多练习与来源 →</a></details>`;}).join('')}</div>`:'';}

function systemFlow(){
 const node=(id,title,detail)=>`<a href="#/blueprint/${id}"><b>${e(title)}</b><small>${e(detail)}</small></a>`;
 const arrow='<span class="journey-flow-arrow" aria-hidden="true">→</span>';
 const lane=(label,nodes)=>`<div class="journey-flow-lane"><h3>${label}</h3>${nodes.join(arrow)}</div>`;
 return `<div class="journey-system-flow" aria-label="机器人模块的四条协作通路">${lane('① 谁决定目标',[node('brain','指令大脑','指令 → 目标列表'),node('agent','Agent 任务状态','保留当前目标和完成进度')])}${lane('② 谁提供现实',[node('data','环境与传感器','位置、速度、相机'),node('vision','感知编码器','相机 → 可见目标位置'),node('agent','Agent 读取观测','目标位置与当前状态汇合')])}${lane('③ 谁比较后果',[node('agent','Agent 发起请求','当前状态 + 当前目标'),node('policy','MPC 规划器','生成候选动作，调用世界模型'),node('world','世界模型','返回候选预测给 MPC，由 MPC 选动作')])}${lane('④ 谁确认完成',[node('policy','执行选定动作','将第一步动作交给环境'),node('data','环境真实变化','返回执行后的观测'),node('agent','Agent 验证与继续','达到目标才推进；否则重规划或报告失败')])}<p class="journey-flow-feedback">↶ 第④步回到第②步。位置/速度可以直接来自传感器；世界模型的预测不能替代执行后的观测。</p><div class="journey-flow-support">${node('training','训练通路','数据 + 监督 → 参数更新；SFT、LoRA、MOPD 放在这里')}${node('evaluation','评测通路','独立数据 + 任务 → 误差、成功、成本与失败证据')}${node('memory','时序组件','为模型保存或读取历史；Attention、SSM、KDA 在这里选择')}</div></div>`;
}

export function blueprintPage(id=''){
 const m=moduleFor(id)||robotModules[0];
 const related=journeyStages.filter(s=>s.module===m.id||s.files.includes(m.path));
 return `<div class="robot-journey">${heading('先有骨架，再按问题替换积木。','目录按职责划分；一个模型可能占多个模块，同一模块也可以有规则、小网络或预训练模型等实现。')}<section class="panel panel-pad"><h2>最终的调用关系</h2>${systemFlow()}<p>这四条通路共享同一套接口。世界模型只负责预测，MPC 负责选择，Agent 负责推进任务；换成直接输出动作的策略后，可以不调用世界模型。训练器更新模型参数，评测器提供独立证据。</p></section><div class="journey-blueprint-layout"><nav class="panel panel-pad journey-tree" aria-label="机器人工程目录"><h2><code>robot-workbench/</code></h2><a href="https://github.com/TatenLee/model-craft/tree/main/projects/robot-workbench" target="_blank" rel="noopener noreferrer">查看真实目录 ↗</a><ul>${robotModules.map(x=>`<li><a class="${x.id===m.id?'active':''}" href="#/blueprint/${x.id}"><code>${e(x.path)}</code><span>${e(x.name)}</span></a></li>`).join('')}</ul><a class="btn" href="./downloads/model-craft-projects.zip" download>下载整个骨架</a></nav><article class="panel panel-pad"><span class="eyebrow">当前积木槽</span><h2>${e(m.name)}</h2><p>${e(m.role)}</p><div class="journey-interface"><span>接头 / 契约</span><code>${e(m.contract)}</code></div><h3>这个位置可以装哪些实现？</h3><ol>${m.variants.map(x=>`<li>${e(x)}</li>`).join('')}</ol><p class="callout">标注“扩展”的实现需要按对应带练接入，不是当前参考工程已经实现的模型。替换之前检查输入语义、shape、dtype、状态生命周期、训练目标和权重兼容。</p><h3>为什么要替换？沿这些阶段看证据</h3><div class="journey-module-stages">${related.map(s=>`<a href="${url(s.id)}"><b>${s.number} · ${e(s.title)}</b><span>${e(s.problem)}</span></a>`).join('')}</div><h3>像更换数据库连接层一样操作</h3><ol><li>写出原实现的输入输出、错误与状态约定。</li><li>在相同接口下加入候选实现，保留原基线。</li><li>接口变化时添加适配，而不是默默让调用者误用。</li><li>先做数值/形状/因果检查，再训练并比较独立任务表现。</li><li>记录改变的文件、配置和权重，失败时能够回退。</li></ol><a class="btn btn-primary" href="${url(m.stage)}">从这个模块第一次出现的地方学起 →</a><a class="text-link" href="${sourceURL(m.path)}" target="_blank" rel="noopener noreferrer">打开对应代码 ↗</a></article></div></div>`;
}

export function placementFor(page,id=''){
 if(page==='lesson')return stageForLesson(id);
 if(page==='day'){const match=id.match(/^w(\d+)-d(\d+)$/);if(!match)return null;const day=Number(match[2]);return stageForLesson(`w${match[1]}-l${Math.min(3,Math.ceil(day/2))}`);}
 if(page==='course')return weekJourney[Number(id)||1];
 if(page==='projects'){if(id.startsWith('workshop-'))return workshopJourney[id.slice(9).split('/')[0]]||null;return mechanismJourney[id]||null;}
 if(page==='code'){const direct=journeyStages.find(s=>s.exerciseId===id);if(direct)return direct.id;if(id.startsWith('lesson-'))return stageForLesson(id.slice(7));if(id.startsWith('project-'))return mechanismJourney[id.slice(8)]||null;const match=id.match(/daily-w(\d+)/);return match?weekJourney[Number(match[1])]:id.startsWith('arch-')?'memory':null;}
 if(page==='concepts'){
  const byStage={fit:['loss','parameters','optimizer','learning-rate','cross-entropy'],evaluate:['metric-benchmark','mmlu','mmmu','mmstar','data-leakage','generalization'],attention:['transformer','encoder-decoder','decoder-only','attention','causal-mask','position','ar'],language:['pretraining','continual-pretraining','tokenizer','self-supervised','perplexity'],sft:['sft','posttraining','loss-mask'],lora:['lora','qlora'],preference:['reward','reward-model','rlhf','dpo','ppo','grpo','image-reward','reward-hacking'],mopd:['mopd','opd','distillation'],vision:['vision-tower','connector','vit','clip','dino','contrastive','mopd-prompts'],representation:['vae','vq','jepa'],world:['world-model','action-conditioning'],plan:['planning','rollout','teacher-forcing'],action:['diffusion','flow-matching','dit','unet','cfg','bc','vla','diffusion-policy','policy'],agent:['agentic','embodied-brain','embodied-model','closed-loop'],memory:['linear-attention','kda','ssm','recurrent-state','tbptt'],systems:['moe','training-inference','gradient-accumulation','loss-reduction','gradient-clip','mixed-precision','fsdp','checkpoint'],audit:['pt','rewardx','lsd','psnr','fid','ablation','reproducibility']};
  const exact=Object.entries(byStage).find(([,ids])=>ids.includes(id));if(exact)return exact[0];const c=concepts.find(c=>c.id===id);return c?weekJourney[c.week]:null;
 }
 if(page==='architectures'){const [view,key]=id.split('/');if(view==='catalog'){const a=architectures.find(x=>x.id===key);return a?architectureJourney[a.group]:null;}return ({foundation:'attention',attention:'attention',sparse:'memory',alternatives:'memory',state:'memory',delta:'memory',capacity:'systems',vision:'vision',generation:'action',embodied:'plan',evaluation:'systems'})[key]||'memory';}
 return null;
}
export function resourceContext(page,id){
 if(['journey','blueprint','library','settings','notebook'].includes(page))return '';
 const target=placementFor(page,id),s=stage(target);
 return `<section class="panel panel-pad journey-resource-context"><span class="eyebrow">按需参考 · 原有记录继续保留</span><p>${s?`这份材料用于 <b>${s.number} · ${e(s.title)}</b>。你来到这里，是为了处理：${e(s.problem)}`:'这是一份可检索的资料或专项练习，不是另一条必须从头重走的课程。先沿机器人主线定位当前问题，再展开需要的内容。'}</p><div class="row wrap"><a class="btn btn-small btn-primary" href="${s?url(s.id):'#/journey'}">${s?'带着结果回到这一站':'回到机器人学习主线'} →</a><a class="btn btn-small" href="#/library">查看材料在主线里的位置</a></div></section>`;
}
let librarySearch='';
function libraryRows(){
 const rows=[...lessons.map(l=>({label:l.title,kind:'原课文',href:`#/lesson/${l.id}`,stage:stageForLesson(l.id)})),...workshops.map(w=>({label:`${w.number} ${w.title}`,kind:'完整工作坊',href:`#/projects/workshop-${w.id}`,stage:workshopJourney[w.id]})),...architectures.map(a=>({label:a.name,kind:architectureGroups.find(g=>g.id===a.group).name,href:`#/architectures/catalog/${a.id}`,stage:architectureJourney[a.group]})),...concepts.map(c=>({label:`${c.term} · ${c.english}`,kind:'概念释义',href:`#/concepts/${c.id}`,stage:placementFor('concepts',c.id)}))];
 const query=librarySearch.trim().toLowerCase();return rows.filter(r=>[r.label,r.kind,stage(r.stage)?.title].join(' ').toLowerCase().includes(query));
}
function libraryResults(){const rows=libraryRows();return `<p role="status" class="small muted">${rows.length} 项材料 · 都有主线位置</p><div class="journey-library-results">${rows.map(r=>`<article class="panel panel-pad"><span class="badge badge-gray">${e(r.kind)}</span><h3><a href="${r.href}">${e(r.label)} ↗</a></h3><p>为什么学它、何时用它：</p>${stageLink(r.stage)}</article>`).join('')||'<p>没有匹配项。试试 MOPD、SSM、视觉、训练或清空关键词。</p>'}</div>`;}
export function libraryPage(){return `<div class="robot-journey">${heading('所有材料，都能回到一个具体问题。','旧课程、结构图和项目已经归位。主线负责顺序与因果，这里负责查阅与扩展。')}<section class="panel panel-pad"><label for="journey-library-search">查一个概念、结构或项目</label><input class="field" type="search" id="journey-library-search" placeholder="MOPD、SFT、DINO、KDA、预训练、世界模型…" value="${e(librarySearch)}"><div class="row wrap space-top"><a class="btn" href="#/journey">机器人主线</a><a class="btn" href="#/blueprint">工程骨架</a><a class="btn" href="#/architectures/map">结构关系图</a><a class="btn" href="#/guide">岗位能力图</a></div><p>原来的 36 节主课已嵌入主线的对应阶段；84 个日单元保留作练习索引。P 是展开实战，M 是机制题，都服务于同一条建造路线。</p></section><div id="journey-library-results">${libraryResults()}</div></div>`;}

export function journeyCompletion(s,state,exercise){const x=journeyStatus(s,state,exercise);return `<div class="journey-completion"><p><b>${x.complete?'✓ 本阶段已有可复核交接':x.ready?'可以保存本阶段交接':'还需要：'+x.missing.join('、')}</b></p><p class="small muted">理解检查 ${x.correct}/${s.checks.length} · ${x.code?'当前代码已验证':'代码待验证'} · ${x.mode==='reuse'?'复用路线':'构造路线'}${state.solutionsViewed?.includes(s.exerciseId)?' · 看过参考解法':''}。任务操作与观察为自查，不代表完整模型效果或岗位认证。</p><button class="btn btn-primary" id="journey-complete" ${x.ready?'':'disabled'}>${x.complete?'更新本阶段交接记录':'保存本阶段交接'}</button></div>`;}

function miniLab(id){
 if(id==='scalar'||id==='fit')return `<div class="journey-mini-lab"><h3>标定台：先猜结果，再改参数</h3><div class="journey-input-grid"><label>w<input id="journey-w" type="number" value="1" step="0.1"></label><label>b<input id="journey-b" type="number" value="0" step="0.1"></label>${id==='fit'?'<label>学习率<input id="journey-lr" type="number" value="0.05" step="0.01" min="0" max="1"></label>':''}</div><div id="journey-calibration" aria-live="polite"></div>${id==='fit'?'<button class="btn btn-small" id="journey-update">用当前错误更新一次 w、b</button>':'<p>这一站先手调参数；下一站解释怎样根据错误自动更新。</p>'}<p class="small muted">输入 [-1,0,1,2]，真实目标 [-1,1,3,5]。MSE 是把每个误差平方后取平均，用来观察参数是否更合适。这里是真实数值计算。</p></div>`;
 if(id==='mopd')return `<div class="journey-mini-lab"><h3>学生已经选了 A：老师会怎样反馈？</h3><div class="journey-input-grid"><label>学生给 A 的概率<input id="journey-student-p" type="number" value="0.2" step="0.05" min="0.01" max="0.99"></label><label>教师给 A 的概率<input id="journey-teacher-p" type="number" value="0.6" step="0.05" min="0.01" max="0.99"></label></div><div id="journey-distill-output" aria-live="polite"></div><p>这是二动作分布和一个采样动作的教学计算。采样信号与完整分布 KL 分开显示；没有训练教师或模拟完整语言模型。</p></div>`;
 return '';
}
export function calibration(w,b){if(![w,b].every(Number.isFinite)||Math.abs(w)>1e6||Math.abs(b)>1e6)throw new Error('请输入有限且绝对值不超过一百万的参数。');const xs=[-1,0,1,2],ys=[-1,1,3,5],pred=xs.map(x=>w*x+b),errors=pred.map((p,i)=>p-ys[i]);return {xs,ys,pred,loss:errors.reduce((n,x)=>n+x*x,0)/4,dw:errors.reduce((n,x,i)=>n+2*x*xs[i],0)/4,db:errors.reduce((n,x)=>n+2*x,0)/4};}
export function distillExample(p,q){if(![p,q].every(x=>Number.isFinite(x)&&x>0&&x<1))throw new Error('概率必须严格位于 0 和 1 之间。');return {signal:Math.log(q)-Math.log(p),reverseKL:p*Math.log(p/q)+(1-p)*Math.log((1-p)/(1-q))};}

export function bindJourney(page,id,state,exercises,save){
 const controller=new window.AbortController(),q=sel=>document.querySelector(sel),on=(el,type,fn)=>el?.addEventListener(type,fn,{signal:controller.signal}),s=page==='journey'?stage(id):null;
 const record=()=>state.journey[s.id]??={mode:'build',answers:{},tasks:[],note:'',completedAt:''};
 const refresh=()=>{const out=q('#journey-completion');if(out&&s)out.innerHTML=journeyCompletion(s,state,exercises.find(x=>x.id===s.exerciseId));};
 document.querySelectorAll('[data-journey-minutes]').forEach(el=>on(el,'click',()=>{state.journeyMinutes=Number(el.dataset.journeyMinutes);save();document.querySelectorAll('[data-journey-minutes]').forEach(button=>{const active=Number(button.dataset.journeyMinutes)===state.journeyMinutes;button.classList.toggle('btn-primary',active);button.setAttribute('aria-pressed',String(active));});q('#journey-session-plan').innerHTML=sessionPlan(state.journeyMinutes);}));
 document.querySelectorAll('[data-journey-scroll]').forEach(el=>on(el,'click',()=>{const target=document.getElementById(el.dataset.journeyScroll);target?.scrollIntoView?.({behavior:'smooth',block:'start'});target?.focus({preventScroll:true});}));
 document.querySelectorAll('[name="journey-mode"]').forEach(el=>on(el,'change',()=>{record().mode=el.value;save();q('#journey-reuse-note').textContent=el.value==='reuse'?s.reuse:'按步骤实现关键接口，保持调用者与验收不变。完整工程已提供；内部推导可以分多次完成。';refresh();}));
 document.querySelectorAll('.journey-task').forEach(el=>on(el,'change',()=>{const r=record(),i=Number(el.value);r.tasks=el.checked?[...new Set([...r.tasks,i])]:r.tasks.filter(v=>v!==i);save();refresh();}));
 document.querySelectorAll('.journey-question').forEach(el=>on(el,'change',ev=>{const i=Number(el.dataset.index),selected=Number(ev.target.value);if(!s.checks[i]?.options[selected])return;record().answers[i]=selected;save();el.querySelector('.journey-answer').innerHTML=answer(s.checks[i],selected);refresh();}));
 on(q('#journey-note'),'input',ev=>{record().note=ev.target.value;save();q('#journey-note-status').textContent='实际观察已保存到本机。';refresh();});
 on(q('#journey-completion'),'click',ev=>{if(!ev.target.closest('#journey-complete')||!s)return;if(journeyStatus(s,state,exercises.find(x=>x.id===s.exerciseId)).ready){record().completedAt=new Date().toISOString();save();refresh();}});
 on(q('#journey-library-search'),'input',ev=>{librarySearch=ev.target.value;q('#journey-library-results').innerHTML=libraryResults();});
 const num=x=>Number(x.toFixed(5));
 function calculate(update=false){const out=q('#journey-calibration');if(!out)return;try{let w=Number(q('#journey-w').value),b=Number(q('#journey-b').value);if(!q('#journey-w').value||!q('#journey-b').value)throw new Error('请填写 w 和 b。');let result=calibration(w,b),before=result.loss;
  if(update){const lr=Number(q('#journey-lr').value);if(!q('#journey-lr').value||!Number.isFinite(lr)||lr<0||lr>1)throw new Error('学习率需在 0–1 之间。');w-=lr*result.dw;b-=lr*result.db;q('#journey-w').value=num(w);q('#journey-b').value=num(b);result=calibration(Number(q('#journey-w').value),Number(q('#journey-b').value));}
  out.innerHTML=`<div class="journey-table-scroll"><table><thead><tr><th>输入 x</th><th>真实 y</th><th>预测</th><th>误差</th></tr></thead><tbody>${result.xs.map((x,i)=>`<tr><td>${x}</td><td>${result.ys[i]}</td><td>${num(result.pred[i])}</td><td>${num(result.pred[i]-result.ys[i])}</td></tr>`).join('')}</tbody></table></div><p><b>MSE：${num(result.loss)}</b>${update?`；更新前 ${num(before)} → 更新后 ${num(result.loss)}`:''}。${s?.id==='fit'?`当前 dw=${num(result.dw)}，db=${num(result.db)}。`:''}</p>`;
 }catch(err){out.innerHTML=`<p role="alert">${e(err.message)}</p>`;}}
 ['w','b','lr'].forEach(id=>on(q(`#journey-${id}`),'input',()=>calculate()));on(q('#journey-update'),'click',()=>calculate(true));calculate();
 function distill(){const out=q('#journey-distill-output');if(!out)return;try{const {signal,reverseKL}=distillExample(Number(q('#journey-student-p').value),Number(q('#journey-teacher-p').value));out.innerHTML=`<p>采样动作 A 的 log-probability 差：<b>${num(signal)}</b>，${signal>0?'教师相对更支持 A。':signal<0?'教师相对更不支持 A。':'两者对 A 的概率相同。'}</p><p>二动作完整分布 reverse KL：<b>${num(reverseKL)}</b>。它考虑两个动作，不等于上面的单点信号。</p>`;}catch(err){out.innerHTML=`<p role="alert">${e(err.message)}</p>`;}}
 ['student-p','teacher-p'].forEach(id=>on(q(`#journey-${id}`),'input',distill));distill();
 return ()=>controller.abort();
}
